package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;
import org.jlinalg.genetics.VepVcf;
import static org.jlinalg.cli.SeuratDifferentialContracts.*;

/** Literal variant consequences with portable native extraction and exact original VEP execution. */
public final class VepToolsCli {
    private VepToolsCli() { }
    static final String ACTION="Read WARNINGS.md, analysis-status.json, execution.json and the retained original stdout/stderr/warnings before downstream use. SKIP3 (exit3): dependent analysis skipped; restore the named exact permitted runtime/resource or retain the skip. FAIL2 (exit2): no complete result; preserve diagnostics, correct the named data/integrity/process/capacity failure and retry NEW output. Never repair alleles, IDs, assembly, missing values or transcripts merely to obtain a result. Original execution requires the exact qualified Linux VEP105/API105 core, exact supplied GTF/GFF and FASTA or the entire byte-bound Ensembl105 human GRCh38 cache/reference bundle. This does not requalify the older LOFTEE host profile. Plugins and other releases require separate qualification. Native extraction retains every CSQ record, all supplied fields, genotypes and variant/allele/gene groups; it does not predict consequences or implement VEP transcript picking. Empty annotation/IMPACT/gene fields are unassessable, never benign or no effect. VERIFY recomputes all five native ledgers from retained VCFs and checks capture/source integrity without running Perl, deserializing the cache, rereading external resources or independently predicting consequences. Hashes provide integrity, not authentication against coordinated replacement. Capacities are monitored/preflight bounds, not OS quotas. No whole-tool or whole-paper reproduction claim.";
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    static int run(String[] args,PrintStream out,PrintStream err) {
        Path root=null;boolean owned=false;var execution=new LinkedHashMap<String,Object>();
        try {
            if(args.length==1&&args[0].equals("--help")){out.println("vep-tools --request UTF8_JSON | --verify BUNDLE\nRUN: NATIVE complete literal CSQ ledgers or ORIGINAL VEP105 with explicit reference and analysis options. See docs/vep-tools.md.\n"+ACTION);return 0;}
            if(args.length==2&&args[0].equals("--verify")){verify(Path.of(args[1]));out.println("Verified saved VEP capture and recomputed every native ledger. "+ACTION);return 0;}
            if(args.length!=2||!args[0].equals("--request"))throw new IOException("Require --request JSON, --verify BUNDLE or --help");
            Path source=Path.of(args[1]).toAbsolutePath().normalize();byte[] original=NextflowFiles.bytes(source,2000000);var raw=object(SimpleJson.parse(StandardCharsets.UTF_8.newDecoder().decode(java.nio.ByteBuffer.wrap(original)).toString()),"request");var r=VepToolsRequest.validate(raw);root=resolve(source.getParent(),text(r,"out"));Files.createDirectories(root.getParent());Files.createDirectory(root);owned=true;
            json(root.resolve("analysis-status.json"),Map.of("status","RUNNING","results_admitted",false));Files.write(root.resolve("source-request.json"),original,StandardOpenOption.CREATE_NEW);for(String name:List.of("inputs","source","worker","results"))Files.createDirectory(root.resolve(name));VepToolsRuntime.sources(root,r,false);execution.put("backend",r.get("backend"));execution.put("whole_paper_reproduced",false);
            VepToolsRuntime.Prepared runtime=text(r,"backend").equals("ORIGINAL")?VepToolsRuntime.prepare(root,source.getParent(),r,execution):null;
            var inputs=VepToolsInputs.prepare(root,source.getParent(),raw,r);json(root.resolve("request.json"),inputs.captured());var effective=VepToolsRequest.validate(inputs.captured());json(root.resolve("effective-request.json"),effective);var reports=new LinkedHashMap<String,Object>();
            if(runtime==null)reports.put("native",VepToolsTables.render(inputs.input(),inputs.annotated(),root.resolve("results/native"),effective,bool(effective,"source_summary_mode",false),false));
            else reports.putAll(VepToolsWorkflow.run(root,effective,inputs,runtime,execution));
            inputs.verify();if(runtime!=null)runtime.verify();VepToolsRuntime.sources(root,effective,true);VepToolsRuntime.capacity(root,effective,false,new long[1]);json(root.resolve("result-summaries.json"),reports);json(root.resolve("execution.json"),execution);Files.writeString(root.resolve("WARNINGS.md"),warning(effective),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);
            json(root.resolve("analysis-status.json"),Map.of("status","COMPLETE_SCOPED_VEP","results_admitted",true,"whole_paper_reproduced",false));seal(root);verify(root);out.println("Completed scoped VEP workflow: "+root);err.println("WARNINGS / REQUIRED ACTIONS: "+root.resolve("WARNINGS.md")+"\n"+ACTION);return 0;
        }catch(Exception|LinkageError|OutOfMemoryError failure){
            int code=failure instanceof VepToolsRuntime.Unavailable?3:2;String state=code==3?"SKIP3_DEPENDENT_ANALYSIS_SKIPPED":"FAIL2_NO_COMPLETE_RESULT";err.println(state+": "+failure+(owned&&root!=null?"\nWARNINGS / REQUIRED ACTIONS: "+root.resolve("WARNINGS.md"):"")+"\n"+ACTION);if(failure instanceof InterruptedException||failure instanceof InterruptedIOException)Thread.currentThread().interrupt();
            if(owned&&root!=null)try{json(root.resolve("execution.json"),execution);try(var trace=new PrintWriter(Files.newBufferedWriter(root.resolve("failure-stack.txt"),StandardCharsets.UTF_8))){failure.printStackTrace(trace);}json(root.resolve("analysis-status.json"),Map.of("status",state,"results_admitted",false,"cause",failure.toString(),"required_action",ACTION));Files.writeString(root.resolve("WARNINGS.md"),"# "+state+"\n\nCAUSE: "+failure+"\n\nREQUIRED ACTION: "+ACTION+"\n",StandardCharsets.UTF_8);seal(root);}catch(IOException e){err.println("Could not seal complete failure diagnostics: "+e+"; preserve the output directory");}return code;
        }
    }
    static void verify(Path supplied)throws IOException {
        Path root=supplied.toAbsolutePath().normalize();var recorded=read(root.resolve("capture-files.json"),268435456);keys(recorded,Set.of("schema_version","authentication","files"));if(integer(recorded,"schema_version",0,1,1)!=1||!Boolean.FALSE.equals(recorded.get("authentication")))throw new IOException("Invalid VEP integrity seal");var actual=hashes(root);actual.remove("capture-files.json");if(!same(actual,object(recorded.get("files"),"files")))throw new IOException("Saved VEP capture population or bytes changed");
        var state=read(root.resolve("analysis-status.json"));if(!Boolean.TRUE.equals(state.get("results_admitted"))||!"COMPLETE_SCOPED_VEP".equals(state.get("status")))throw new IOException("Failed/skipped VEP capture is not a complete result");var saved=read(root.resolve("request.json"));var r=VepToolsRequest.validate(saved);if(!".".equals(saved.get("out"))||!same(r,read(root.resolve("effective-request.json"))))throw new IOException("Saved/effective VEP request changed");VepToolsRuntime.sources(root,r,true);Map<String,Object> reports=new LinkedHashMap<>();
        if(text(r,"backend").equals("NATIVE")){
            Path original=saved.containsKey("original_vcf")?vcf(root,saved,"original_vcf","original"):null;Path annotated=vcf(root,saved,"annotated_vcf","annotated");reports.put("native",VepToolsTables.render(original,annotated,root.resolve("results/native"),r,bool(r,"source_summary_mode",false),true));if(!read(root.resolve("input-summary.json")).isEmpty())throw new IOException("Native input summary changed");
        }else{
            Path input=vcf(root,saved,"input_vcf","original");verifyReferenceLedger(root,r,input);var ids=new LinkedHashSet<String>();
            for(Object item:list(r.get("analyses"),"analyses")){var a=object(item,"analysis");String id=text(a,"id");ids.add(id);var options=object(a.get("options"),"options");reports.put(id,VepToolsTables.render(input,root.resolve("worker/"+id+"/original.vcf"),root.resolve("results/"+id),r,Set.of("most_severe","summary").contains(options.get("transcript_mode")),true));}
            if(!children(root.resolve("results")).equals(ids))throw new IOException("Original VEP result IDs changed");verifySavedReferences(root,r);
        }
        if(!same(reports,read(root.resolve("result-summaries.json"))))throw new IOException("VEP result summary binding differs");if(!Files.readString(root.resolve("WARNINGS.md"),StandardCharsets.UTF_8).equals(warning(r)))throw new IOException("VEP warning/source scope changed");VepToolsRuntime.capacity(root,r,false,new long[1]);
    }
    private static void verifySavedReferences(Path root,Map<String,Object> r)throws IOException {
        var ref=object(r.get("reference"),"reference");String kind=text(ref,"kind");if(kind.startsWith("human-cache")){
            var binding=read(root.resolve("reference-bindings.json"),67108864);var profile=object(SimpleJson.parse(new String(VepToolsRuntime.resource("REFERENCE.json"),StandardCharsets.UTF_8)),"reference profile");var pins=new TreeMap<>(object(profile.get("files"),"reference files"));byte[] bytes=VepToolsRuntime.resource("REFERENCE.json");pins.put("PROFILE.json",Map.of("bytes",bytes.length,"sha256",NextflowFiles.sha(bytes)));if(!same(binding.get("complete_file_identities"),pins)||!same(binding.get("source_archives"),profile.get("source_archives"))||!same(binding.get("profile"),profile.get("profile"))||!text(ref,"bundle").equals(binding.get("root"))||!Boolean.FALSE.equals(binding.get("subset_or_version_substitution")))throw new IOException("Saved entire-reference identity binding differs");
        }else{var original=object(read(root.resolve("source-request.json")).get("reference"),"original reference");String sourceName=text(original,"annotation");sourceName=VepToolsInputs.annotationName(sourceName.substring(sourceName.lastIndexOf('/')+1));for(String key:List.of("fasta","fai","annotation")){String expected="inputs/reference/"+switch(key){case "fasta"->"genome.fa";case "fai"->"genome.fa.fai";default->"transcripts/"+sourceName;};if(!expected.equals(ref.get(key)))throw new IOException("Saved reference path escaped capture or original annotation basename changed");}}
        int n=0;for(Object item:list(r.get("custom_annotations"),"custom annotations")){var c=object(item,"custom annotation");String format=text(c,"format"),expected="inputs/custom-"+(n++)+"/"+(format.equals("bigwig")?"annotation.bw":"annotation."+format+".gz");if(!expected.equals(c.get("file")))throw new IOException("Saved custom annotation path escaped capture");}
    }
    private static void verifyReferenceLedger(Path root,Map<String,Object> r,Path input)throws IOException {
        try(var ledger=Files.newBufferedReader(root.resolve("reference-checks.tsv"),StandardCharsets.UTF_8)){
            if(!"input_row\tCHROM\tPOS\toriginal_REF\treference_bases\tstatus".equals(ledger.readLine()))throw new IOException("Reference ledger header changed");long[] uncertain={0};var population=VepVcf.inspectOriginal(input,VepToolsInputs.limits(r),v->{String line=ledger.readLine();if(line==null||line.length()>VepToolsRequest.number(r,"maximum_line_characters")*3)throw new IOException("Reference ledger missing/oversized row");String[] fields=line.split("\t",-1);var original=v.fields();if(fields.length!=6||!fields[0].equals(Long.toString(v.row()))||!fields[1].equals(original.get(0))||!fields[2].equals(original.get(1))||!fields[3].equals(original.get(3))||fields[4].length()!=fields[3].length()||!fields[4].matches("[ACGTNacgtn]+"))throw new IOException("Reference ledger population/literal input differs");boolean unknown=(fields[3]+fields[4]).toUpperCase(Locale.ROOT).indexOf('N')>=0;String status=unknown?"UNASSESSABLE_N_BASES_RETAINED":"MATCHED_LITERAL_SEQUENCE";if(!fields[5].equals(status)||!unknown&&!fields[3].equalsIgnoreCase(fields[4]))throw new IOException("Reference ledger match/uncertainty claim differs");if(unknown)uncertain[0]++;});if(ledger.readLine()!=null)throw new IOException("Extra reference ledger rows");var expected=Map.of("variants",population.variants(),"alternate_alleles",population.alternateAlleles(),"reference_unassessable_rows",uncertain[0],"contig_aliasing_or_allele_repair",false,"assembly_labels_independently_certified",false);if(!same(expected,read(root.resolve("input-summary.json"))))throw new IOException("Reference input summary differs");
        }
    }
    private static Path vcf(Path root,Map<String,Object> saved,String key,String leaf)throws IOException {String name=text(saved,key);if(!Set.of("inputs/"+leaf+".vcf","inputs/"+leaf+".vcf.gz").contains(name))throw new IOException("Saved VCF path escaped capture");return root.resolve(name);}
    private static Set<String> children(Path root)throws IOException{try(var stream=Files.list(root)){return stream.map(p->p.getFileName().toString()).collect(java.util.stream.Collectors.toSet());}}
    private static String warning(Map<String,Object> r){return "# VEP — WARNINGS AND REQUIRED ACTIONS\n\n"+ACTION+"\n\nBackend: "+r.get("backend")+". All requested analyses use the complete captured input population. Options absent from the source command retain VEP's own defaults and auto-enabling behavior; they are not reported as disabled. Source --most_severe/--summary may leave allele, gene, feature and IMPACT blank; these remain unassigned, with no inferred ALLELE_NUM. Multiple transcript consequences are retained at the variant–allele–gene unit. A maximum observed IMPACT summarizes supplied annotations and does not establish that missing annotations are low impact. Custom annotation indexes are newly generated from exact captured BGZF data. Original warnings are retained even on exit0. Numeric performance, clinical pathogenicity, author gene masks and whole-paper replication are not established by consequence annotation.\n";}
    static Map<String,String> hashes(Path root)throws IOException {
        Map<String,String> result=new TreeMap<>();Path real=root.toRealPath();long[] nodes={0};Files.walkFileTree(root,new SimpleFileVisitor<>(){
            private void guard(Path p)throws IOException{if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("VEP capture integrity inspection interrupted");if(++nodes[0]>2200000||Files.isSymbolicLink(p)||!p.toRealPath().equals(real.resolve(root.relativize(p))))throw new IOException("VEP capture capacity exceeded or path alias found");}
            @Override public FileVisitResult preVisitDirectory(Path p,BasicFileAttributes a)throws IOException{guard(p);return FileVisitResult.CONTINUE;}
            @Override public FileVisitResult visitFile(Path p,BasicFileAttributes a)throws IOException{guard(p);if(!a.isRegularFile())throw new IOException("Nonregular VEP capture member");result.put(root.relativize(p).toString().replace('\\','/'),FollowupSupport.hash(p));return FileVisitResult.CONTINUE;}
        });return result;
    }
    static void seal(Path root)throws IOException{var files=hashes(root);files.remove("capture-files.json");json(root.resolve("capture-files.json"),Map.of("schema_version",1,"authentication",false,"files",files));}
}
